import os
import tomllib
from typing import Any, Optional


class ConfigError(Exception):
    def __init__(self, key: str, expected: str, actual: Optional[str] = None):
        self.key = key
        self.expected = expected
        self.actual = actual
        msg = f"{key}: expected {expected}"
        if actual is not None:
            msg += f" (got '{actual}')"
        super().__init__(msg)


def _coerce(value: str, expected_type: type) -> Any:
    if expected_type is int:
        return int(value)
    if expected_type is float:
        return float(value)
    if expected_type is bool:
        return value.lower() in ("true", "1", "yes")
    return value


def load(
    defaults: dict, toml_path: Optional[str] = None, prefix: str = "APP", env: Optional[dict] = None
) -> dict:
    if env is None:
        env = dict(os.environ)
    cfg = dict(defaults)
    if toml_path is not None:
        try:
            with open(toml_path, "rb") as f:
                cfg.update(tomllib.load(f))
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if not key.startswith(prefix + "__"):
            continue
        rest = key[len(prefix) + 2 :]
        parts = rest.split("__")
        target = cfg
        for part in parts[:-1]:
            if part not in target:
                raise ConfigError(rest, "missing default")
            target = target[part]
        final_key = parts[-1]
        if final_key not in target:
            raise ConfigError(rest, "missing default")
        expected_type = type(target[final_key])
        coerced = _coerce(value, expected_type)
        if coerced is None and expected_type is not str:
            raise ConfigError(rest, "missing default")
        target[final_key] = coerced
    return cfg
